\begin{proof}
Let
\[
\mathbf a=(a_{1},\dots ,a_{n}),\qquad 
\mathbf b=(b_{1},\dots ,b_{n})\in\mathbb R^{n},
\]
and denote the Euclidean inner product and norm by
\[
\langle\mathbf a,\mathbf b\rangle=\sum_{i=1}^{n}a_{i}b_{i},
\qquad 
\|\mathbf a\|=\sqrt{\langle\mathbf a,\mathbf a\rangle}
          =\sqrt{\sum_{i=1}^{n}a_{i}^{2}} .
\]

\medskip
\noindent\textbf{1. A non‑negative quadratic form.}
For any real number $t$ consider
\[
f(t)=\|\mathbf a+t\mathbf b\|^{2}
    =\langle\mathbf a+t\mathbf b,\mathbf a+t\mathbf b\rangle .
\]
Expanding the inner product we obtain
\begin{align*}
f(t)&=\sum_{i=1}^{n}(a_{i}+t b_{i})^{2} \\[2pt]
    &=\sum_{i=1}^{n}a_{i}^{2}
      +2t\sum_{i=1}^{n}a_{i}b_{i}
      +t^{2}\sum_{i=1}^{n}b_{i}^{2}.
\end{align*}
Hence
\begin{equation}
f(t)=\|\mathbf a\|^{2}+2t\langle\mathbf a,\mathbf b\rangle
      +t^{2}\|\mathbf b\|^{2}. \tag{1}
\end{equation}
Since a squared norm is always non‑negative,
\begin{equation}
f(t)\ge 0\qquad\forall\,t\in\mathbb R . \tag{2}
\end{equation}

\medskip
\noindent\textbf{2. Discriminant condition.}
Equation \eqref{1} is a quadratic polynomial in $t$ of the form $At^{2}+Bt+C$ with
\[
A=\|\mathbf b\|^{2},\qquad
B=2\langle\mathbf a,\mathbf b\rangle,\qquad
C=\|\mathbf a\|^{2}.
\]
A quadratic with $A>0$ is non‑negative for all real $t$ iff its discriminant satisfies $B^{2}-4AC\le 0$. Thus
\[
\Delta:=B^{2}-4AC
      =\bigl(2\langle\mathbf a,\mathbf b\rangle\bigr)^{2}
       -4\|\mathbf a\|^{2}\|\mathbf b\|^{2}
     =4\Bigl[\langle\mathbf a,\mathbf b\rangle^{2}
        -\|\mathbf a\|^{2}\|\mathbf b\|^{2}\Bigr]. \tag{3}
\]
From the non‑negativity we have $\Delta\le 0$, and dividing \eqref{3} by $4>0$ yields
\[
\langle\mathbf a,\mathbf b\rangle^{2}
   \le \|\mathbf a\|^{2}\,\|\mathbf b\|^{2}.
\]
Writing the inner products and norms in summation notation we obtain the Cauchy–Schwarz inequality
\[
\boxed{\Bigl(\sum_{i=1}^{n}a_{i}b_{i}\Bigr)^{2}
       \le
       \Bigl(\sum_{i=1}^{n}a_{i}^{2}\Bigr)
       \Bigl(\sum_{i=1}^{n}b_{i}^{2}\Bigr)}. \tag{4}
\]

\medskip
\noindent\textbf{3. Edge (degenerate) cases.}
If $\mathbf a=\mathbf 0$ or $\mathbf b=\mathbf 0$, both sides of \eqref{4} are $0$, so the inequality holds trivially. In the discriminant computation this corresponds to $A=0$ or $C=0$, and $\Delta\le 0$ reduces to $0\le 0$.

\medskip
\noindent\textbf{4. Equality condition.}
Equality in \eqref{4} occurs exactly when $\Delta=0$, i.e. when
\begin{equation}
\langle\mathbf a,\mathbf b\rangle^{2}
   =\|\mathbf a\|^{2}\|\mathbf b\|^{2}. \tag{5}
\end{equation}
Assume $\|\mathbf b\|^{2}>0$. Then the quadratic $f(t)$ in \eqref{1} has a single real root
\[
t_{0}= -\frac{B}{2A}= -\frac{\langle\mathbf a,\mathbf b\rangle}{\|\mathbf b\|^{2}} .
\]
Because $f(t_{0})=0$, we have $\mathbf a+t_{0}\mathbf b=\mathbf 0$, i.e. $\mathbf a = -t_{0}\mathbf b$. Setting $k=-t_{0}$ we obtain $\mathbf a = k\mathbf b$, or componentwise $a_{i}=k\,b_{i}$ for $i=1,\dots ,n$.
Conversely, if $a_{i}=k\,b_{i}$ for some $k\in\mathbb R$, then
\[
\sum a_{i}b_{i}=k\sum b_{i}^{2},\qquad
\sum a_{i}^{2}=k^{2}\sum b_{i}^{2},
\]
and substitution into \eqref{4} shows that equality holds. The case $\|\mathbf b\|^{2}=0$ (i.e. $\mathbf b=\mathbf 0$) is covered by the degenerate situation where both vectors are zero, which also satisfies the proportionality condition.

Hence equality holds if and only if the two vectors are linearly dependent, i.e. there exists $k\in\mathbb R$ such that $a_{i}=k\,b_{i}$ for all $i$ (including $k=0$ when one vector is zero).

\end{proof}
